<template>
  <div class="flex flex-col gap-4" data-testid="campaign-stats">
    <Alert v-if="data?.note" data-testid="campaign-stats-note">
      <InfoIcon class="h-4 w-4" />
      <AlertDescription class="text-xs">{{ data.note }}</AlertDescription>
    </Alert>
    <SystemDashboardNavigation :params="params" :default-date="defaultDate" :calculated-at="data?.calculated_at" />
    <AppLoader v-if="isLoading" subject="campaign stats" />
    <AppError v-else-if="error" title="Failed to load campaign stats" :error="error" />
    <AppEmpty v-else-if="!data?.charts?.length" subject="campaign stats" />
    <div v-else class="grid grid-cols-12 gap-4">
      <DashboardChartsCard :charts="data.charts" :params="params" :query-key="queryKey" :map-type="null" />
    </div>
  </div>
</template>

<script setup lang="ts">
import { InfoIcon } from 'lucide-vue-next';
import { Alert, AlertDescription } from '~/components/ui/alert';
import {
  getCampaignStats,
  type CampaignDashboardRecruitmentResponse,
  type GetCampaignDetailsResponse,
  type GetCampaignStatsData,
} from '~/client';

// The parent route passes `campaign` to every child via <NuxtPage :campaign>. Declaring it here binds it
// as a prop instead of letting it fall through to a DOM attribute (which logs a Vue warning); this page
// loads its own stats by id and does not read it.
defineProps<{
  campaign?: GetCampaignDetailsResponse;
}>();

definePageMeta({
  roles: ['admin', 'manager'],
  backGroup: 'campaign-dashboard',
  backLabel: 'dashboard',
});

useHead({
  title: 'Campaign Stats',
});

const route = useRoute();

const campaignId = computed(() => useRoute('recruitment-campaigns-id-stats').params.id);

const defaultDate = computed(() => defaultDashboardDateRange());

const params = computed(() => dashboardQueryParams<GetCampaignStatsData['query']>(route.query, defaultDate.value));

const queryKey = computed(() => ['recruitment-campaign.stats', campaignId.value, params.value]);

const { data, error, isLoading } = useQuery({
  key: () => queryKey.value,
  query: (): Promise<CampaignDashboardRecruitmentResponse> =>
    getCampaignStats({ composable: '$fetch', path: { campaign_id: campaignId.value }, query: params }),
  enabled: () => !!campaignId.value && route.name === 'recruitment-campaigns-id-stats',
});
</script>
